window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[63]={"id":"063","numero":63,"titre":"Trouble schizophrénique","objectifs":[{"id":"63-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des idées délirantes et des hallucinations","contenu":"<p>Une <span class=\"kw-def\">idée délirante</span> est une <strong>altération du contenu de la pensée</strong> entraînant une <span class=\"kw-alerte\">perte du contact avec la réalité</span>. Elle se définit par :</p>\n      <ul>\n        <li><strong>Déduction incorrecte</strong> concernant la réalité extérieure</li>\n        <li>Conviction <strong>inébranlable</strong>, fermement soutenue en dépit de l'opinion partagée par le groupe socio-culturel</li>\n        <li>Maintenue malgré <strong>toute preuve incontestable du contraire</strong></li>\n        <li><span class=\"kw-clinique\">Inaccessible au raisonnement</span> ou à la contestation par <span class=\"kw-clinique\">les</span> faits — il s'agit d'une « évidence interne », plausible ou invraisemblable</li>\n      </ul>\n      <p>Une <span class=\"kw-def\">hallucination</span> est une <strong><span class=\"kw-def\">perception sans objet</span> à percevoir</strong>. On en distingue <span class=\"kw-chiffre\">2 types</span> :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Intrapsychique</strong></td><td><span class=\"kw-clinique\">Perte de l'intimité psychique</span> ; <strong>absence de sensorialité et de spatialité</strong> ; phénomène vécu dans la propre pensée du patient, perçu comme étranger à lui</td></tr>\n          <tr><td><strong>Sensorielle</strong></td><td><strong>Présence de sensorialité, de spatialité</strong> et de conviction de réalité ; peut toucher <span class=\"kw-clinique\">les</span> 5 sens (auditif, visuel, tactile, olfactif/gustatif, cénesthésique)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Une hallucination n'est <strong>pas forcément associée</strong> à une idée délirante. Quand une idée délirante est construite secondairement à partir d'une hallucination, on parle de <span class=\"kw-def\">mécanisme hallucinatoire</span>.</div>","frequence":1},{"id":"63-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition des schizophrénies","contenu":"<p>La <span class=\"kw-def\">schizophrénie</span> est un <strong>trouble psychiatrique fréquent</strong>, actuellement classé parmi <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">10 maladies les plus invalidantes</span> par l'OMS. Elle fait partie des <span class=\"kw-def\">troubles psychotiques chroniques</span>, caractérisés par une <span class=\"kw-alerte\">altération du contact avec la réalité</span>.</p>\n      <p>Le <span class=\"kw-def\">diagnostic positif</span> repose sur l'association de plusieurs critères :</p>\n      <ul>\n        <li>Association d'<strong>au moins 2 syndromes</strong> parmi : syndrome <span class=\"kw-clinique\">positif</span>, syndrome <span class=\"kw-clinique\">négatif</span>, syndrome de <span class=\"kw-clinique\">désorganisation</span></li>\n        <li>Symptômes de la phase active présents <span class=\"kw-chiffre\">≥ 1 mois</span> (ou moins en cas de traitement efficace)</li>\n        <li><span class=\"kw-alerte\">Retentissement fonctionnel</span> social ou professionnel depuis le début des troubles</li>\n        <li>Durée totale d'<span class=\"kw-clinique\">évolution</span> <span class=\"kw-chiffre\">≥ 6 mois</span></li>\n      </ul>\n      <div class=\"callout callout-info\">⚠️ Selon la durée du retentissement fonctionnel : <strong>trouble psychotique bref</strong> si <span class=\"kw-chiffre\">1 jour – 1 mois</span> ; <strong>trouble schizophréniforme</strong> si <span class=\"kw-chiffre\">1 – 6 mois</span> ; <strong><span class=\"kw-def\">schizophrénie</span></strong> si <span class=\"kw-chiffre\">≥ 6 mois</span>.</div>","frequence":1},{"id":"63-3","rang":"A","rubrique":"Définition","titre":"Connaître les dimensions cliniques des schizophrénies","contenu":"<p>La sémiologie de la <span class=\"kw-def\">schizophrénie</span> s'organise en <strong><span class=\"kw-chiffre\">3 dimensions</span> cliniques</strong> (ou syndromes). Le diagnostic ex<span class=\"kw-chiffre\">ige</span> l'association d'<strong>au moins 2 de ces 3 syndromes</strong>.</p>\n      <table >\n        <thead><tr><th>Dimension</th><th>Définition</th><th>Manifestations clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Syndrome positif</strong></td><td>Productions psychiques en excès, absentes chez le sujet sain</td><td><span class=\"kw-clinique\">Idées délirantes</span> ; <span class=\"kw-clinique\">hallucinations</span></td></tr>\n          <tr><td><strong>Syndrome négatif</strong></td><td>Appauvrissement de la vie psychique</td><td><span class=\"kw-clinique\">Émoussement affectif</span> ; <span class=\"kw-clinique\">alogie</span> ; <span class=\"kw-clinique\">retrait social</span> ; aboulie</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Syndrome de désorganisation</span></strong></td><td>Perte de l'unité psychique entre cognitions, émotions et comportements</td><td>Désorganisation <span class=\"kw-clinique\">affective</span>, <span class=\"kw-clinique\">comportementale</span> et <span class=\"kw-clinique\">cognitive</span></td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"63-4","rang":"B","rubrique":"Définition","titre":"Connaître la définition du trouble schizo-affectif","contenu":"<p>Le <span class=\"kw-etio\">trouble schizo-affectif</span> associe des symptômes de <span class=\"kw-def\">schizophrénie</span> et des <strong>symptômes thymiques</strong> (dépressifs ou maniaques). Le diagnostic est retenu lorsque <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes thymiques</span> sont présents pendant <strong>une partie conséquente de la durée totale</strong> des périodes actives et résiduelles de la maladie.</p>\n      <div class=\"callout callout-warn\"><strong>À distinguer.</strong> Face à des syndromes positif / négatif / désorganisation associés à un syndrome thymique, deux situations :\n        <ul>\n          <li><strong><span class=\"kw-etio\">Trouble schizo-affectif</span></strong> — <span class=\"kw-clinique\">les</span> symptômes thymiques occupent une part conséquente de l'<span class=\"kw-clinique\">évolution</span></li>\n          <li><strong><span class=\"kw-clinique\">Épisode thymique</span> avec <span class=\"kw-clinique\">caractéristiques psychotiques</span></strong> — lorsque le syndrome dépressif ou maniaque disparaît, <span class=\"kw-clinique\">les</span> syndromes positif / négatif / désorganisation <span class=\"kw-alerte\">disparaissent complètement</span></li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif</em></p>","frequence":1},{"id":"63-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence, la morbi-mortalité","contenu":"<table >\n        <thead><tr><th>Paramètre</th><th>Donnée</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">0,4 – 0,7 %</span> de la population (trouble fréquent)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Incidence</span></strong></td><td><span class=\"kw-chiffre\">26 nouveaux cas / 100 000 personnes / an</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span></strong></td><td><span class=\"kw-alerte\">2 à 3 × plus élevée</span> que dans la population générale ; espérance de vie diminuée</td></tr>\n          <tr><td><strong>Causes de surmortalité</strong></td><td><strong><span class=\"kw-etio\">Maladies cardiovasculaires</span> :</strong> cause principale<br><strong>Suicide :</strong> concerne <span class=\"kw-alerte\">≈ 5 %</span> des patients souffrant de <span class=\"kw-def\">schizophrénie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ La <span class=\"kw-def\">schizophrénie</span> figure parmi <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">10 maladies les plus invalidantes</span> selon l'OMS.</div>","frequence":1},{"id":"63-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, le pronostic et l’évolution","contenu":"<p><strong><span class=\"kw-def\">Facteurs de risque</span>.</strong> La <span class=\"kw-def\">schizophrénie</span> résulte de l'interaction d'une vulnérabilité propre et de facteurs précipitants :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Facteurs génétiques</span> — modèle <span class=\"kw-def\">polygénique</span> ; chaque personne possède un degré de vulnérabilité propre</li>\n        <li><span class=\"kw-etio\">Facteurs environnementaux</span> — <span class=\"kw-etio\">complications obstétricales</span>, urbanisation, migration, consommation de <span class=\"kw-etio\">cannabis</span></li>\n      </ul>\n      <p><strong><span class=\"kw-clinique\">Évolution</span>.</strong> Variable mais généralement <span class=\"kw-alerte\">chronique</span> : épisodes aigus ± espacés, intervalles inter-épisodes ± symptomatiques. Le déficit se stabilise généralement après <span class=\"kw-chiffre\">2 à 5 ans</span> d'évolution. Une <span class=\"kw-clinique\">rémission</span> complète, voire une guérison, est possible dans <span class=\"kw-chiffre\">20 à 25 %</span> des cas.</p>\n      <p><strong>Facteurs de bon <span class=\"kw-def\">pronostic</span> :</strong></p>\n      <ul>\n        <li>Sexe <span class=\"kw-clinique\">féminin</span></li>\n        <li>Bon fonctionnement pré-morbide</li>\n        <li>Début <span class=\"kw-clinique\">tardif</span></li>\n        <li>Bonne conscience du trouble</li>\n        <li>Prise en charge précoce, environnement favorable, traitement antipsychotique bien <span class=\"kw-def\">suivi</span></li>\n      </ul>","frequence":2},{"id":"63-7","rang":"B","rubrique":"Physiopathologie","titre":"Savoir que l’étiologie est multifactorielle","contenu":"<p>L'étiologie de la <span class=\"kw-def\">schizophrénie</span> est <strong>multifactorielle</strong> et complexe : elle repose sur l'<strong>interaction</strong> de plusieurs déterminants.</p>\n      <ul>\n        <li><span class=\"kw-etio\">Facteurs de vulnérabilité génétiques</span> — modèle <strong><span class=\"kw-def\">polygénique</span></strong> ; chaque personne possède un degré de vulnérabilité propre</li>\n        <li><span class=\"kw-etio\">Facteurs environnementaux</span> — <span class=\"kw-etio\">complications obstétricales</span>, urbanisation, migration, consommation de <span class=\"kw-etio\">cannabis</span></li>\n        <li><span class=\"kw-def\">Hypothèse neurodéveloppementale</span> — prévalente aujourd'hui : la <span class=\"kw-def\">schizophrénie</span> serait la <strong>conséquence retardée d'anomalies du neurodéveloppement</strong>, débutant des années avant le début de la maladie</li>\n      </ul>","frequence":0},{"id":"63-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’analyse sémiologique d’un syndrome délirant","contenu":"<p>Tout <span class=\"kw-def\">syndrome délirant</span> s'analyse selon <strong><span class=\"kw-chiffre\">5 axes</span></strong> : le <strong>thème</strong>, le <strong>mécanisme</strong>, la <strong>systématisation</strong>, l'<strong>adhésion</strong> et le <strong>retentissement</strong>.</p>\n      <p><strong>Thèmes délirants</strong> <span class=\"kw-clinique\">les</span> plus fréquents dans la <span class=\"kw-def\">schizophrénie</span> :</p>\n      <table >\n        <thead><tr><th>Thème</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Persécution</span></strong></td><td>Le sujet se sent attaqué, harcelé, espionné ou victime d'une conspiration</td></tr>\n          <tr><td><strong>Grandeur / mégalomaniaque</strong></td><td>Sentiment exagéré de son importance, de son pouvoir, de son savoir ou de son identité</td></tr>\n          <tr><td><strong>Mystique</strong></td><td>Thème central religieux</td></tr>\n          <tr><td><strong>Somatique</strong></td><td>Thème touchant au fonctionnement du corps</td></tr>\n          <tr><td><strong>De référence</strong></td><td>Des éléments de l'environnement auraient une signification particulière pour le sujet</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Mécanismes délirants</strong> — processus de construction de l'idée délirante :</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Interprétatif</span></strong></td><td>Attribution d'un <strong>sens erroné à un fait réel</strong></td></tr>\n          <tr><td><strong>Hallucinatoire</strong></td><td>Idée délirante construite <strong>à partir d'une hallucination</strong></td></tr>\n          <tr><td><strong>Intuitif</strong></td><td>Idée fausse admise <strong>sans vérification ni raisonnement</strong>, hors de toute donnée objective ou sensorielle</td></tr>\n          <tr><td><strong>Imaginatif</strong></td><td><strong>Fabulation ou invention</strong> où l'imagination est au premier plan</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Systématisation et adhésion</strong> — comparaison <span class=\"kw-def\">schizophrénie</span> <span class=\"kw-bio\">vs</span> trouble délirant persistant :</p>\n      <table >\n        <thead><tr><th>Axe</th><th><span class=\"kw-def\">Schizophrénie</span></th><th><span class=\"kw-etio\">Trouble délirant persistant</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Thèmes</strong></td><td><span class=\"kw-clinique\">Multiples, hétérogènes</span></td><td>Thème généralement <span class=\"kw-clinique\">unique</span> (persécution surtout)</td></tr>\n          <tr><td><strong>Mécanismes</strong></td><td>Généralement nombreux</td><td><span class=\"kw-def\">Interprétatif</span>, intuitif, imaginatif</td></tr>\n          <tr><td><strong>Systématisation</strong></td><td><span class=\"kw-alerte\">Non systématisé</span> — organisation floue, incohérente, sans logique</td><td>Majoritairement <strong>systématisé</strong> (logique apparente)</td></tr>\n          <tr><td><strong>Adhésion</strong></td><td>Variable : <strong>partielle</strong> (le patient peut critiquer ses idées) ou <strong>totale</strong> (conviction inébranlable)</td><td><strong>Totale</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Retentissement — à évaluer systématiquement.</strong> Toute idée délirante impose d'évaluer le retentissement émotionnel et comportemental : niveau d'<span class=\"kw-clinique\">anxiété</span> (souvent majeur), <span class=\"kw-alerte\">risque suicidaire</span>, <span class=\"kw-alerte\">risque de passage à l'acte hétéro-agressif</span> (expier ses fautes, se venger d'un persécuteur).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 65 — Trouble délirant persistant</em></p>","frequence":2},{"id":"63-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le mode d’apparition des troubles schizophréniques","contenu":"<p>Le trouble schizophrénique apparaît typiquement à la <strong>fin de l'adolescence ou chez l'adulte jeune</strong> (<span class=\"kw-chiffre\">15 – 25 ans</span>). On distingue deux modes de début, de fréquence équivalente.</p>\n      <table >\n        <thead><tr><th></th><th>Début aigu (≈ <span class=\"kw-chiffre\">50 %</span>)</th><th>Début insidieux (≈ <span class=\"kw-chiffre\">50 %</span>)</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Installation</strong></td><td>Épisode psychotique aigu</td><td>Manifestations discrètes évoluant sur des <span class=\"kw-chiffre\">mois à années</span> ; diagnostic souvent porté tardivement</td></tr>\n          <tr><td><strong>Prodromes</strong></td><td>Symptômes non spécifiques dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 – 4 ans</span> avant ; symptômes psychotiques atténués dans l'année précédente</td><td><span class=\"kw-clinique\">Retrait social</span> progressif : fléchissement scolaire / professionnel, désintérêt des activités habituelles</td></tr>\n          <tr><td><strong>Facteurs précipitants</strong></td><td>Événements stressants ; consommation de <span class=\"kw-etio\">substances psychoactives</span> (cannabis)</td><td>—</td></tr>\n          <tr><td><strong>Syndrome prédominant</strong></td><td>Syndromes <span class=\"kw-clinique\">positif</span> et de <span class=\"kw-clinique\">désorganisation</span> très marqués ; le syndrome négatif apparaît au décours</td><td>Syndrome <span class=\"kw-clinique\">négatif</span> au premier plan</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Formes selon l'âge de début :</strong></p>\n      <ul>\n        <li><strong>Formes précoces</strong> — début <span class=\"kw-chiffre\">&lt; 18 ans</span> (très précoce si <span class=\"kw-chiffre\">&lt; 13 ans</span>) ; antécédents développementaux fréquents</li>\n        <li><strong>Formes tardives</strong> — début <span class=\"kw-chiffre\">&gt; 35 ans</span> ; prédominance féminine (<span class=\"kw-chiffre\">7 F / 1 H</span>) ; symptomatologie hallucinatoire riche, peu de désorganisation</li>\n      </ul>","frequence":2},{"id":"63-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le syndrome positif","contenu":"<p>Le <span class=\"kw-def\">syndrome positif</span> regroupe <span class=\"kw-clinique\">les</span> <strong>productions psychiques en excès</strong> : idées délirantes et hallucinations.</p>\n      <p><strong>Idées délirantes</strong> — <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">&gt; 90 %</span> dans la <span class=\"kw-def\">schizophrénie</span>. Thèmes multiples et hétérogènes, mécanismes variés, délire le plus souvent <span class=\"kw-alerte\">non systématisé</span>.</p>\n      <p><strong>Hallucinations</strong> — <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">75 %</span>, surtout en phase aiguë. Tous <span class=\"kw-clinique\">les</span> sens peuvent être touchés.</p>\n      <table >\n        <thead><tr><th>Type sensoriel</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Auditives (≈ <span class=\"kw-chiffre\">50 %</span>)</strong></td><td>Sons simples possibles ; surtout <span class=\"kw-clinique\">hallucinations acoustico-verbales</span> : voix nettement localisées dans l'espace, conversant entre elles, s'adressant au sujet à la 3ᵉ personne, phrases courtes à connotation négative<br><strong>Signes évocateurs :</strong> attitudes d'écoute ; moyens de protection (musique, se boucher <span class=\"kw-clinique\">les</span> oreilles) ; <span class=\"kw-clinique\">soliloquie</span> ; distractibilité pendant l'entretien</td></tr>\n          <tr><td><strong>Visuelles (≈ <span class=\"kw-chiffre\">30 %</span>)</strong></td><td>Élémentaires (lumières, taches colorées, phosphènes, ombres) ou complexes (objets, figures, scènes)</td></tr>\n          <tr><td><strong>Tactiles (≈ <span class=\"kw-chiffre\">5 %</span>)</strong></td><td>Coups de vent sur le visage, brûlures, piqûres, sensation de parasites sur le corps</td></tr>\n          <tr><td><strong>Moins fréquentes</strong></td><td>Gustatives ; olfactives (mauvaises odeurs émanant du patient lui-même) ; cénesthésiques (sensibilité interne, impressions de transformation du corps)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Hallucinations intrapsychiques</strong> — phénomène vécu dans la pensée du patient, sans manifestation sensorielle, traduisant une <span class=\"kw-clinique\">perte de l'intimité psychique</span> : vol, divulgation, devinement, transmission de la pensée, pensées imposées, écho de la pensée.</p>\n      <div class=\"callout callout-info\">⚠️ Une hallucination n'est pas forcément délirante. Quand l'idée délirante en découle, on parle de <span class=\"kw-def\">mécanisme hallucinatoire</span>.</div>","frequence":2},{"id":"63-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le syndrome négatif","contenu":"<p>Le <span class=\"kw-def\">syndrome négatif</span> correspond à un <strong>appauvrissement de la vie psychique</strong>. Il conditionne fortement le <span class=\"kw-def\">pronostic</span> fonctionnel et est <span class=\"kw-alerte\">peu accessible au traitement pharmacologique</span>.</p>\n      <table >\n        <thead><tr><th>Versant</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Affectif</strong></td><td><span class=\"kw-def\">Anhédonie</span> : perte de la capacité à éprouver du plaisir<br><span class=\"kw-def\">Émoussement des affects</span> : absence d'émotions dans l'expression du visage et l'intonation de la voix, regard fixe, corps figé, sourire rare, impression de froideur et de détachement</td></tr>\n          <tr><td><strong>Cognitif</strong></td><td><span class=\"kw-def\">Alogie</span> / pauvreté du discours : difficultés à converser, <span class=\"kw-clinique\">réponses brèves</span></td></tr>\n          <tr><td><strong>Comportemental</strong></td><td><span class=\"kw-clinique\">Retrait social</span> : vie relationnelle pauvre, sans recherche de <span class=\"kw-def\">contact</span><br><span class=\"kw-def\">Aboulie</span> : incapacité à mettre en œuvre une action déjà planifiée, par diminution de la motivation<br><span class=\"kw-def\">Apragmatisme</span> : incapacité à entreprendre et à planifier des actions — au maximum <span class=\"kw-def\">clinophilie</span> (rester au lit) puis <span class=\"kw-alerte\">incurie</span> (négligence de l'hygiène)</td></tr>\n        </tbody>\n      </table>","frequence":4},{"id":"63-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître le syndrome de désorganisation","contenu":"<p>Le <span class=\"kw-def\">syndrome de désorganisation</span> traduit la <strong>perte de l'unité psychique</strong> entre cognitions, émotions et comportements. Il s'exprime sur trois versants.</p>\n      <table >\n        <thead><tr><th>Versant</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Affective</strong></td><td><span class=\"kw-def\">Ambivalence affective</span> : affects contradictoires simultanés pour un même objet<br>Réaction affective inappropriée ; <span class=\"kw-def\">discordance idio-affective</span> : incohérence entre le discours et <span class=\"kw-clinique\">les</span> émotions exprimées (sourires discordants, rires immotivés)</td></tr>\n          <tr><td><strong>Comportementale</strong></td><td><span class=\"kw-def\">Maniérisme gestuel</span> : mauvaise coordination des mouvements<br>Ambivalence comportementale ; <span class=\"kw-def\">parakinésies</span> : décharges motrices imprévisibles ; <span class=\"kw-def\">paramimies</span> : discordance entre la mimique et le contenu psycho-affectif</td></tr>\n          <tr><td><strong>Cognitive</strong></td><td><strong>Pensée :</strong> discours diffluent, propos décousus ; <span class=\"kw-def\">barrages</span> (interruption brusque du discours) ; <span class=\"kw-def\">fading</span> (ralentissement et baisse du volume sonore)<br><strong>Logique :</strong> <span class=\"kw-def\">rationalisme morbide</span> ; <span class=\"kw-def\">raisonnement paralogique</span> ; altération des capacités d'abstraction<br><strong>Langage :</strong> <span class=\"kw-def\">néologismes</span> ; <span class=\"kw-def\">paralogismes</span> ; <span class=\"kw-def\">schizophasie</span> au maximum (néo-langage incompréhensible)</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"63-13","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les principaux diagnostics différentiels non psychiatriques","contenu":"<p>Devant un tableau psychotique, en particulier un <strong>premier épisode</strong>, il faut systématiquement éliminer une <span class=\"kw-alerte\">cause organique ou toxique</span> avant de retenir une <span class=\"kw-def\">schizophrénie</span>.</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Neurologiques</strong></td><td><span class=\"kw-etio\">Épilepsie</span> ; tumeurs cérébrales ; <span class=\"kw-etio\">encéphalite herpétique</span> ou à <span class=\"kw-bio\">anticorps anti-neuronaux</span> ; maladie de Huntington ; <span class=\"kw-etio\">neurolupus</span></td></tr>\n          <tr><td><strong>Endocriniennes</strong></td><td><span class=\"kw-etio\">Dysthyroïdies</span> ; altération de l'axe corticotrope</td></tr>\n          <tr><td><strong>Métaboliques</strong></td><td>Maladie de <span class=\"kw-etio\">Wilson</span> ; maladie de Niemann-Pick type C</td></tr>\n          <tr><td><strong>Infectieuses</strong></td><td><span class=\"kw-etio\">Neurosyphilis</span> ; <span class=\"kw-etio\">SIDA</span></td></tr>\n          <tr><td><strong>Substances psychoactives</strong></td><td>Intoxication aiguë ou chronique au <span class=\"kw-etio\">cannabis</span> ; <span class=\"kw-etio\">amphétamines</span> ; anticholinergiques, LSD, <span class=\"kw-ttt\">kétamine</span>, phencyclidine</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Bilan paraclinique d'élimination :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Bilan biologique standard</span> — <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">TSH</span></li>\n        <li>Recherche de <span class=\"kw-bio\">toxiques urinaires</span> — cannabis, cocaïne, <span class=\"kw-ttt\">opioïdes</span>, amphétamines</li>\n        <li><span class=\"kw-imagerie\">Imagerie cérébrale</span> (<span class=\"kw-imagerie\">IRM</span> au mieux) — surtout si signe d'appel ou présentation atypique</li>\n        <li><span class=\"kw-bio\">EEG</span> — utile lors d'un premier épisode pour éliminer une comitialité</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> diagnostique.</strong> Une <span class=\"kw-alerte\">encéphalite</span> (herpétique, ou <span class=\"kw-etio\">auto-immune</span> à <span class=\"kw-bio\">anticorps anti-neuronaux</span>) peut se présenter comme un premier épisode psychotique : tout tableau atypique impose le bilan organique avant l'étiquette psychiatrique.</div>","frequence":0},{"id":"63-14","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques","contenu":"<p><span class=\"kw-clinique\">Les</span> principaux <strong>diagnostics différentiels psychiatriques</strong> du trouble schizophrénique :</p>\n      <table >\n        <thead><tr><th>Diagnostic</th><th>Élément discriminant</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Troubles de l'humeur</strong></td><td>Épisode dépressif ou maniaque avec <span class=\"kw-clinique\">caractéristiques psychotiques</span> : <span class=\"kw-clinique\">les</span> symptômes psychotiques <span class=\"kw-alerte\">disparaissent avec le syndrome thymique</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Trouble schizo-affectif</span></strong></td><td>Symptômes thymiques présents pendant une part conséquente de l'<span class=\"kw-clinique\">évolution</span></td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Trouble délirant persistant</span></strong></td><td>Syndrome positif <span class=\"kw-alerte\">sans éléments de bizarrerie</span> ni désorganisation ; délire systématisé, thème unique</td></tr>\n          <tr><td><strong>Troubles du neurodéveloppement</strong></td><td>Repli sur soi de type autistique, sans syndrome positif ni désorganisation</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> La présence de syndromes positif, négatif ou de désorganisation ne conduit <strong>pas automatiquement</strong> au diagnostic de <span class=\"kw-def\">schizophrénie</span> : s'il existe un syndrome thymique associé, évoquer un trouble schizo-affectif ou un épisode thymique avec <span class=\"kw-clinique\">caractéristiques psychotiques</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 65 — Trouble délirant persistant · 66 — Trouble dépressif</em></p>","frequence":2},{"id":"63-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p>La prise en charge du trouble schizophrénique est <strong>globale et au long cours</strong> : elle articule traitement pharmacologique, psychothérapie et accompagnement psycho-social.</p>\n      <p><strong>Indications d'<span class=\"kw-alerte\">hospitalisation</span></strong> en service de psychiatrie (en <span class=\"kw-alerte\">urgence</span> ou non) :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Épisode aigu</span> avec troubles du comportement</li>\n        <li><span class=\"kw-alerte\">Risque suicidaire</span> ou de mise en danger</li>\n        <li><span class=\"kw-alerte\">Risque hétéro-agressif</span></li>\n      </ul>\n      <p>Le <strong>traitement pharmacologique</strong> poursuit <span class=\"kw-chiffre\">3 objectifs</span> :</p>\n      <ul>\n        <li><strong>Épisode aigu</strong> — contrôle rapide des symptômes mettant en danger le patient et son entourage</li>\n        <li><strong>Traitement de fond</strong> — choix et adaptation selon l'<span class=\"kw-clinique\">évolution</span> des symptômes et la tolérance</li>\n        <li><strong>Phase de <span class=\"kw-clinique\">rémission</span></strong> — diminuer le risque de rechute et le retentissement de la maladie</li>\n      </ul>\n      <p>S'y ajoutent <span class=\"kw-clinique\">les</span> volets non pharmacologiques : <span class=\"kw-clinique\">psychothérapie</span>, <span class=\"kw-clinique\">remédiation cognitive</span>, ECT, et prise en charge psycho-sociale (<span class=\"kw-def\">ALD</span> <span class=\"kw-chiffre\">100 %</span>, réinsertion).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement · 351 — Agitation et délire aigu · 353 — Risque et conduite suicidaire</em></p>","frequence":2},{"id":"63-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications du traitement pharmacologique de la phase aiguë","contenu":"<p>L'<span class=\"kw-def\">épisode aigu</span> est caractérisé par la recrudescence des symptômes (idées délirantes, hallucinations, désorganisation, repli). Le <strong><span class=\"kw-ttt\">traitement antipsychotique</span> doit impérativement être initié ou modifié rapidement</strong>.</p>\n      <p>En cas d'<span class=\"kw-clinique\">anxiété</span> ou d'<span class=\"kw-clinique\">agitation modérée</span>, un traitement symptomatique sédatif est associé — <span class=\"kw-chiffre\">2 possibilités</span> :</p>\n      <ul>\n        <li><span class=\"kw-ttt\">Antipsychotiques « sédatifs » de 1ʳᵉ génération</span> — ex. cyamémazine, lévomépromazine</li>\n        <li><span class=\"kw-ttt\">Benzodiazépines</span> — ex. <span class=\"kw-ttt\">diazépam</span>, <span class=\"kw-ttt\">oxazépam</span> ; facilitent la poursuite de la prise en charge et l'introduction de l'antipsychotique</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span> thérapeutique.</strong> Le diagnostic de <span class=\"kw-def\">schizophrénie</span> peut être posé avec une durée de symptômes <span class=\"kw-chiffre\">&lt; 1 mois</span> si le traitement est efficace : on n'attend <strong>pas</strong> un mois pour traiter un épisode aigu.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes · 351 — Agitation et délire aigu</em></p>","frequence":0},{"id":"63-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du traitement pharmacologique au long cours","contenu":"<p>Le traitement au long cours vise une <strong><span class=\"kw-ttt\">monothérapie</span> antipsychotique</strong>, à la dose minimale efficace (principe « start low, go slow »).</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>1ʳᵉ intention</strong></td><td><span class=\"kw-ttt\">Antipsychotiques de 2ᵉ génération</span> [QARA] : <span class=\"kw-ttt\">quétiapine</span>, amisulpride, rispéridone, aripiprazole</td></tr>\n          <tr><td><strong>Inefficacité / résistance</strong></td><td>Un autre antipsychotique peut être proposé ; en cas de <span class=\"kw-alerte\">résistance à 2 antipsychotiques de 2ᵉ génération</span> à posologie efficace et durée suffisante → <span class=\"kw-ttt\">clozapine</span></td></tr>\n          <tr><td><strong>Observance difficile</strong></td><td>Formes d'action prolongée « retard » IM [ROA] : <span class=\"kw-ttt\">rispéridone</span>, <span class=\"kw-ttt\">olanzapine</span>, <span class=\"kw-ttt\">aripiprazole</span> (1 injection toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">15 j</span>, 3 sem, 4 sem ou <span class=\"kw-chiffre\">3 mois</span>)</td></tr>\n          <tr><td><strong>Durée</strong></td><td>Après un 1ᵉʳ épisode psychotique : <span class=\"kw-chiffre\">≥ 2 ans</span> après la <span class=\"kw-clinique\">rémission</span> complète<br>Après un 2ᵉ épisode ou une rechute : <span class=\"kw-chiffre\">≥ 5 ans</span> après la rémission complète</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> L'<span class=\"kw-alerte\">inobservance est la 1ʳᵉ cause d'inefficacité</span> du traitement antipsychotique → <span class=\"kw-def\">suivi</span> rapproché de l'efficacité et de la tolérance.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":2},{"id":"63-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du traitement non pharmacologique au long cours","contenu":"<p><span class=\"kw-clinique\">Les</span> traitements <strong>non pharmacologiques</strong> sont indissociables du traitement de fond et ciblent les dimensions peu sensibles aux antipsychotiques.</p>\n      <table >\n        <thead><tr><th>Modalité</th><th>Objectif / indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Psychothérapie cognitivo-comportementale</strong></td><td>Réduire l'impact des <span class=\"kw-clinique\">symptômes persistants</span> malgré un traitement antipsychotique bien conduit</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Éducation thérapeutique</span></strong></td><td>Envers le patient et ses proches ; réduit le <span class=\"kw-clinique\">risque de rechute</span></td></tr>\n          <tr><td><strong>Remédiation cognitive</strong></td><td>Agit sur <span class=\"kw-clinique\">les</span> altérations cognitives (attention, mémoire, fonctions exécutives) et la cognition sociale (reconnaissance des émotions, attribution d'intention à autrui)</td></tr>\n          <tr><td><strong>ECT</strong> (électro-convulsivothérapie)</td><td>3 indications : <span class=\"kw-clinique\">épisodes thymiques</span> ; <span class=\"kw-clinique\">syndrome positif résistant</span> ; <span class=\"kw-clinique\">syndrome catatonique</span> associé</td></tr>\n          <tr><td><strong>Prise en charge psycho-sociale</strong></td><td>Ouverture des droits de prise en charge à <span class=\"kw-chiffre\">100 %</span> (<span class=\"kw-def\">ALD</span>) ; réadaptation et réinsertion psycho-sociale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ La <strong>stimulation magnétique transcrânienne</strong> (rTMS) peut être utilisée pour <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">hallucinations résistantes</span>.</div>","frequence":1},{"id":"63-19","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des comorbidités non psychiatriques, le rôle du médecin généraliste","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">comorbidités</span> non psychiatriques concernent <span class=\"kw-chiffre\">≈ 50 %</span> des patients et participent à la <span class=\"kw-alerte\">surmortalité</span> de la <span class=\"kw-def\">schizophrénie</span>. Leur <span class=\"kw-def\">dépistage</span> et leur <span class=\"kw-def\">suivi</span> relèvent largement du <strong>médecin généraliste</strong>.</p>\n      <table >\n        <thead><tr><th>Type</th><th>Comorbidités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Addictologiques</strong></td><td><span class=\"kw-clinique\">Tabac</span> (≈ <span class=\"kw-chiffre\">60 %</span>) ; <span class=\"kw-etio\">cannabis</span> (≈ <span class=\"kw-chiffre\">50 %</span>) ; <span class=\"kw-clinique\">alcool</span> — usage à risque ou dépendance (<span class=\"kw-chiffre\">10 – 50 %</span>)</td></tr>\n          <tr><td><strong>Métaboliques et cardiovasculaires</strong></td><td><span class=\"kw-clinique\">Diabète</span> ; <span class=\"kw-clinique\">obésité</span> (≈ <span class=\"kw-chiffre\">50 %</span>) ; <span class=\"kw-clinique\">HTA</span> ; <span class=\"kw-clinique\">dyslipidémie</span> → <span class=\"kw-alerte\">syndrome métabolique</span> (≈ <span class=\"kw-chiffre\">30 %</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Cette surreprésentation s'explique en partie par <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">effets indésirables métaboliques des antipsychotiques</span>, mais aussi par des <span class=\"kw-def\">facteurs de risque</span> associés (<span class=\"kw-etio\">tabagisme</span>, <span class=\"kw-etio\">sédentarité</span>).</p>\n      <div class=\"callout callout-info\"><strong>Rôle du médecin généraliste.</strong> <span class=\"kw-def\">Dépistage</span> et <span class=\"kw-def\">suivi</span> des <span class=\"kw-def\">comorbidités</span> métaboliques et cardiovasculaires, <span class=\"kw-def\">surveillance</span> de la tolérance du traitement antipsychotique, coordination du parcours de soins somatiques.</div>","frequence":0}],"astuces":[{"type":"tip","titre":"Mnémo « 3 syndromes » pour décrire toute schizophrénie","contenu":"<p>Devant un tableau de <span class=\"kw-def\">schizophrénie</span>, structure systématiquement la sémiologie en <strong>3 syndromes</strong> :</p>\n<ol>\n  <li><strong>Positif</strong> = <span class=\"kw-clinique\">délire</span> + <span class=\"kw-clinique\">hallucinations</span> + automatisme mental</li>\n  <li><strong>Négatif</strong> = émoussement + <span class=\"kw-clinique\">alogie</span> + <span class=\"kw-clinique\">avolition</span> + <span class=\"kw-clinique\">anhédonie</span> + retrait</li>\n  <li><strong><span class=\"kw-clinique\">Désorganisation</span></strong> = pensée + langage + affects + comportement (<span class=\"kw-clinique\">catatonie</span>)</li>\n</ol>\n<p>Le <span class=\"kw-def\">DSM-5</span> ajoute <span class=\"kw-clinique\">les</span> dimensions <strong>cognitive</strong> (mémoire, attention, fonctions exécutives) et <strong>thymique</strong> (dépression post-psychotique, <span class=\"kw-alerte\">risque suicidaire</span>). En QCM, citer les 5 dimensions = points garantis.</p>"},{"type":"danger","titre":"Piège EDN : éliminer l'organique avant le diagnostic","contenu":"<p>Toute <strong>1ʳᵉ <span class=\"kw-clinique\">poussée</span> <span class=\"kw-def\">psychotique</span></strong> impose un <strong>bilan organique systématique</strong> avant d'évoquer une <span class=\"kw-def\">schizophrénie</span> ou de prescrire un AP au long cours :</p>\n<ul>\n  <li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">iono</span>, <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">BHC</span>, <span class=\"kw-bio\">urée</span>/<span class=\"kw-bio\">créat</span>, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">β-hCG</span></li>\n  <li><span class=\"kw-bio\">BU</span> + toxiques urinaires (<span class=\"kw-etio\">cannabis</span>, <span class=\"kw-etio\">amphétamines</span>, <span class=\"kw-etio\">cocaïne</span>, <span class=\"kw-etio\">LSD</span>)</li>\n  <li><span class=\"kw-bio\">Sérologies</span> <span class=\"kw-etio\">VIH</span>, <span class=\"kw-clinique\">syphilis</span> (± Lyme, hépatites)</li>\n  <li><strong><span class=\"kw-imagerie\">TDM</span> ou <span class=\"kw-imagerie\">IRM cérébrale</span> + <span class=\"kw-imagerie\">EEG</span></strong></li>\n  <li><strong>PL si <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">confusion</span>, signes neuro</strong> → <span class=\"kw-alerte\">encéphalite</span> <span class=\"kw-etio\">anti-NMDA</span> (sujet jeune, autonomic instability, mouvements anormaux) — <span class=\"kw-alerte\">à ne jamais manquer</span></li>\n</ul>\n<p>Signes d'orientation organique : début brutal, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">confusion</span>, signes neuro focaux, mouvements anormaux, <span class=\"kw-clinique\">hallucinations</span> visuelles isolées, âge &lt; 12 ou &gt; <span class=\"kw-chiffre\">45 ans</span>.</p>"},{"type":"warn","titre":"Discriminants : schizophrénie vs trouble bipolaire vs trouble délirant persistant","contenu":"<table class=\"matrix\"><thead><tr><th>Critère</th><th><span class=\"kw-def\">Schizophrénie</span></th><th>Trouble bipolaire</th><th>Trouble <span class=\"kw-clinique\">délirant</span> persistant</th></tr></thead><tbody>\n<tr><td><span class=\"kw-clinique\">Délire</span></td><td>Polymorphe, non systématisé, mécanisme hallucinatoire</td><td>Congruent à l'humeur, présent uniquement pendant <span class=\"kw-clinique\">les</span> épisodes</td><td>Systématisé, non bizarre (<span class=\"kw-clinique\">persécution</span>, <span class=\"kw-clinique\">jalousie</span>, <span class=\"kw-clinique\">érotomanie</span>)</td></tr>\n<tr><td>Symptômes négatifs</td><td>++ (entre <span class=\"kw-clinique\">les</span> épisodes)</td><td>Absents en intercritique</td><td>Absents</td></tr>\n<tr><td><span class=\"kw-clinique\">Désorganisation</span></td><td>+++</td><td>Absente</td><td>Absente</td></tr>\n<tr><td>Fonctionnement</td><td>Détérioration progressive</td><td>Préservé en intercritique</td><td>Préservé en dehors du <span class=\"kw-clinique\">délire</span></td></tr>\n<tr><td>Âge de début</td><td><span class=\"kw-chiffre\">15-35 ans</span></td><td><span class=\"kw-chiffre\">15-25 ans</span></td><td>&gt; <span class=\"kw-chiffre\">40 ans</span></td></tr>\n<tr><td>Traitement</td><td><span class=\"kw-ttt\">AP2G</span> ± <span class=\"kw-ttt\">clozapine</span></td><td><span class=\"kw-ttt\">Thymorégulateur</span> (<span class=\"kw-ttt\">lithium</span>)</td><td><span class=\"kw-ttt\">AP2G</span> dose modérée</td></tr>\n</tbody></table>\n<p>Le <strong><span class=\"kw-def\">trouble schizo-affectif</span></strong> se positionne entre <span class=\"kw-def\">schizophrénie</span> et bipolarité : épisode thymique concomitant + ≥ <span class=\"kw-chiffre\">2 sem</span> de symptômes psychotiques sans humeur.</p>"},{"type":"info","titre":"Astuce PU : « QARA » pour les AP2G de 1ʳᵉ intention","contenu":"<p>En 1ʳᵉ intention dans la <span class=\"kw-def\">schizophrénie</span>, retiens le mnémo <strong>QARA</strong> :</p>\n<ul>\n  <li><strong>Q</strong>uétiapine</li>\n  <li><strong>A</strong>misulpride</li>\n  <li><strong>R</strong>ispéridone</li>\n  <li><strong>A</strong>ripiprazole</li>\n</ul>\n<p><span class=\"kw-ttt\">Olanzapine</span> est aussi très utilisée mais avec un profil métabolique défavorable (prise de poids, <span class=\"kw-etio\">diabète</span>).</p>\n<p><strong><span class=\"kw-ttt\">Clozapine</span> = la dernière carte</strong> (<span class=\"kw-def\">schizophrénie résistante</span> : échec de <span class=\"kw-chiffre\">≥ 2</span> AP). <span class=\"kw-bio\">NFS</span> hebdo × <span class=\"kw-chiffre\">18 sem</span> puis mensuelle à vie. Seule efficace dans cette indication, seule efficace sur le <span class=\"kw-alerte\">risque suicidaire</span>.</p>\n<p><strong>Mnémo durée du traitement</strong> : <strong>2-5-vie</strong> = ≥ <span class=\"kw-chiffre\">2 ans</span> après 1ᵉʳ épisode, ≥ <span class=\"kw-chiffre\">5 ans</span> après <span class=\"kw-alerte\">rechute</span>, à vie après <span class=\"kw-chiffre\">≥ 3</span> épisodes.</p>"},{"type":"tip","titre":"Catatonie : ne pas la rater, BZD avant ECT","contenu":"<p>La <strong><span class=\"kw-clinique\">catatonie</span></strong> (5 signes cardinaux : <span class=\"kw-clinique\">stupeur</span>, <span class=\"kw-clinique\">mutisme</span>, <span class=\"kw-clinique\">négativisme</span>, <span class=\"kw-clinique\">catalepsie</span>, <span class=\"kw-clinique\">flexibilité cireuse</span>) est une <span class=\"kw-alerte\">urgence vitale</span> :</p>\n<ul>\n  <li>Complications : <span class=\"kw-alerte\">déshydratation</span>, <span class=\"kw-alerte\">embolie pulmonaire</span>, <span class=\"kw-alerte\">rhabdomyolyse</span>, escarres</li>\n  <li>Traitement : <strong><span class=\"kw-ttt\">lorazépam</span> à fortes doses (1ʳᵉ intention)</strong>, puis <strong><span class=\"kw-ttt\">ECT</span></strong> si échec</li>\n  <li><strong>Ne pas donner d'AP en 1ʳᵉ intention</strong> : risque de <span class=\"kw-alerte\">syndrome malin</span> et d'aggravation</li>\n  <li>Échelle de Bush-Francis pour le <span class=\"kw-def\">dépistage</span></li>\n</ul>\n<p>Étiologies : <span class=\"kw-def\">schizophrénie</span>, trouble bipolaire, dépression sévère, MAIS aussi organique (<span class=\"kw-alerte\">encéphalite</span> <span class=\"kw-etio\">anti-NMDA</span>, neurolepticomalin, <span class=\"kw-clinique\">lupus</span>) — bilan étiologique systématique.</p>"}],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> <span class=\"kw-alerte\">épisode aigu</span> avec recrudescence des <span class=\"kw-clinique\">idées délirantes</span>, <span class=\"kw-clinique\">hallucinations</span> et <span class=\"kw-clinique\">désorganisation</span> → le <span class=\"kw-ttt\">traitement antipsychotique</span> doit être <span class=\"kw-alerte\">initié ou modifié rapidement</span>.<br><strong>Fenêtre :</strong> on n'attend pas <span class=\"kw-chiffre\">1 mois</span> pour traiter — le diagnostic peut être posé en <span class=\"kw-chiffre\">moins d'1 mois</span> en cas de <span class=\"kw-ttt\">traitement efficace</span>.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">éliminer une cause non-psychiatrique</span> (bilan + <span class=\"kw-bio\">toxiques urinaires</span>) puis évaluer la <span class=\"kw-alerte\">dangerosité</span> pour soi et autrui.</p>","hospit":"<p><strong>Orientation :</strong> <span class=\"kw-ttt\">hospitalisation en service de psychiatrie</span> (en <span class=\"kw-alerte\">urgence</span> ou non) selon la gravité ; sinon <span class=\"kw-ttt\">suivi spécialisé</span> avec introduction de l'<span class=\"kw-ttt\">antipsychotique</span>.<br><strong>Indications d'<span class=\"kw-alerte\">hospitalisation</span> :</strong> <span class=\"kw-alerte\">épisode aigu avec troubles du comportement</span>, <span class=\"kw-alerte\">risque suicidaire ou de mise en danger</span>, <span class=\"kw-alerte\">risque hétéro-agressif</span>.<br><strong>Au long cours :</strong> partenariat structures sanitaires + médico-sociales et <span class=\"kw-ttt\">prise en charge à 100%</span> pour faciliter l'accès aux soins.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Risque suicidaire</span> : le <span class=\"kw-alerte\">suicide</span> concerne <span class=\"kw-chiffre\">5%</span> des patients schizophrènes</li><li><span class=\"kw-alerte\">Risque de passage à l'acte hétéro-agressif</span></li><li><span class=\"kw-alerte\">Gestes auto ou hétéro-agressifs impulsifs et bizarres</span>, sans explication</li><li><span class=\"kw-clinique\">Niveau d'anxiété majeur</span> avec risque de <span class=\"kw-alerte\">mise en danger</span></li><li><span class=\"kw-alerte\">Dangerosité pour soi-même ou autrui</span>, conséquence directe des <span class=\"kw-clinique\">idées délirantes</span> (expier ses fautes, se venger d'un persécuteur)</li><li><span class=\"kw-alerte\">Mortalité 2 à 3 fois plus élevée</span>, de cause principalement <span class=\"kw-etio\">cardiovasculaire</span></li></ul>","principes":"<p>Éliminer une <span class=\"kw-etio\">cause non-psychiatrique</span>, traiter l'<span class=\"kw-alerte\">épisode aigu</span>, puis instaurer un <span class=\"kw-ttt\">traitement de fond</span> en <span class=\"kw-ttt\">monothérapie antipsychotique</span>.</p><p><strong>Éliminer un <span class=\"kw-def\">diagnostic différentiel</span> non-psychiatrique</strong></p><p>Causes à évoquer : <span class=\"kw-etio\">épilepsie</span>, <span class=\"kw-etio\">encéphalite herpétique ou auto-immune</span>, <span class=\"kw-etio\">dysthyroïdie</span>, <span class=\"kw-etio\">maladie de Wilson</span>, <span class=\"kw-etio\">neurosyphilis</span>, intoxication au <span class=\"kw-etio\">cannabis</span> ou aux <span class=\"kw-etio\">amphétamines</span>.</p><ul><li><span class=\"kw-bio\">Bilan biologique standard</span> : <span class=\"kw-bio\">glycémie</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">TSH</span></li><li>Recherche de <span class=\"kw-bio\">toxiques urinaires</span> : cannabis, cocaïne, <span class=\"kw-ttt\">opioïdes</span>, amphétamines</li><li><span class=\"kw-imagerie\">IRM cérébrale</span> si <span class=\"kw-alerte\">signe d'appel</span> ou manifestations atypiques</li><li><span class=\"kw-bio\">EEG</span> au 1er épisode pour éliminer une comitialité</li></ul><p><strong>Phase aiguë</strong></p><ul><li><span class=\"kw-ttt\">Antipsychotique</span> initié ou modifié rapidement</li><li>Si <span class=\"kw-clinique\">anxiété ou agitation modérée</span> : <span class=\"kw-ttt\">antipsychotique sédatif de 1ère génération</span> (cyamémazine, lévomépromazine)</li><li>Ou <span class=\"kw-ttt\">benzodiazépine</span> (<span class=\"kw-ttt\">diazépam</span>, <span class=\"kw-ttt\">oxazépam</span>) pour faciliter l'introduction de l'antipsychotique</li></ul><p><strong>Traitement de fond (long cours)</strong></p><p>Durée : <span class=\"kw-chiffre\">≥ 2 ans</span> après un 1er épisode unique, <span class=\"kw-chiffre\">≥ 5 ans</span> après un 2e épisode ou une rechute.</p><ul><li><span class=\"kw-chiffre\">1ère intention</span> : <span class=\"kw-ttt\">antipsychotique de 2e génération</span> en monothérapie [QARA : <span class=\"kw-ttt\">quétiapine</span>, amisulpride, rispéridone, aripiprazole]</li><li>Principe « <span class=\"kw-ttt\">start low, go slow</span> » : débuter à faible dose puis viser la dose minimale efficace</li><li>Si <span class=\"kw-alerte\">résistance à 2 antipsychotiques de 2e génération</span> bien conduits : <span class=\"kw-ttt\">clozapine</span></li><li>Si <span class=\"kw-clinique\">observance difficile</span> : <span class=\"kw-ttt\">forme retard IM</span> [ROA : rispéridone, <span class=\"kw-ttt\">olanzapine</span>, aripiprazole]</li></ul><p><strong>Non pharmacologique</strong></p><ul><li><span class=\"kw-ttt\">Psychothérapie cognitivo-comportementale</span> (réduit l'impact des symptômes persistants)</li><li><span class=\"kw-ttt\">Éducation thérapeutique</span> du patient et des proches (réduit le risque de rechute)</li><li><span class=\"kw-ttt\">Remédiation cognitive</span> (attention, mémoire, fonctions exécutives, cognition sociale)</li><li><span class=\"kw-ttt\">ECT</span> si épisodes thymiques, syndrome positif résistant ou syndrome catatonique</li></ul>","suivi":"<p><strong>Observance :</strong> l'<span class=\"kw-alerte\">inobservance est la 1ère cause d'inefficacité</span> → <span class=\"kw-def\">suivi</span> régulier de l'<span class=\"kw-ttt\">efficacité</span> et de la <span class=\"kw-ttt\">tolérance</span> du traitement antipsychotique.<br><strong><span class=\"kw-def\">Comorbidités</span> :</strong> dépister le <span class=\"kw-etio\">syndrome métabolique</span> (<span class=\"kw-etio\">diabète</span>, obésité, HTA, dyslipidémie, ~<span class=\"kw-chiffre\">30%</span>) — rôle du <span class=\"kw-ttt\">médecin généraliste</span>.<br><strong><span class=\"kw-alerte\">Risque vital</span> :</strong> surveiller le <span class=\"kw-alerte\">risque suicidaire</span> et la <span class=\"kw-etio\">morbi-mortalité cardiovasculaire</span> (espérance de vie réduite).</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Épisode psychotique aigu / suspicion de schizophrénie — Idées délirantes, hallucinations, désorganisation","detail":"<h4>CAT — Épisode psychotique aigu / schizophrénie — Du <span class=\"kw-def\">diagnostic différentiel</span> à l'orientation et au traitement</h4>","branches":[{"to":"q-organique","label":"Recrudescence des symptômes","color":"blue"}]},{"id":"q-organique","kind":"decision","label":"Cause non-psychiatrique éliminée ? — Bilan bio, toxiques urinaires, IRM si atypie, EEG","branches":[{"to":"t-organique","label":"Non / signe d'appel","color":"blue"},{"to":"q-gravite","label":"Oui (cause psychiatrique)","color":"amber"}]},{"id":"t-organique","kind":"terminal","label":"Prendre en charge la cause organique / toxique","color":"blue","detail":"<h4>Conduite</h4><ul><li>Traiter la <span class=\"kw-etio\">pathologie causale</span> identifiée (neurologique, endocrinienne, métabolique, infectieuse)</li><li>Éliminer en priorité une <span class=\"kw-etio\">intoxication au cannabis ou aux amphétamines</span></li></ul>"},{"id":"q-gravite","kind":"decision","label":"Signes de gravité présents ? — Troubles du comportement, risque suicidaire ou hétéro-agressif","branches":[{"to":"t-hospit","label":"Oui","color":"red"},{"to":"t-ambu","label":"Non","color":"amber"}]},{"id":"t-hospit","kind":"terminal","label":"Hospitalisation en psychiatrie (en urgence)","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Épisode aigu avec troubles du comportement</span></li><li><span class=\"kw-alerte\">Risque suicidaire ou de mise en danger</span></li><li><span class=\"kw-alerte\">Risque hétéro-agressif</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antipsychotique</span> initié ou modifié rapidement</li><li><span class=\"kw-ttt\">Sédation</span> si agitation : <span class=\"kw-ttt\">antipsychotique sédatif 1G</span> ou <span class=\"kw-ttt\">benzodiazépine</span></li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Antipsychotique + suivi spécialisé ambulatoire","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-chiffre\">1ère intention</span> : <span class=\"kw-ttt\">antipsychotique de 2e génération</span> en monothérapie [QARA]</li><li>« <span class=\"kw-ttt\">start low, go slow</span> », dose minimale efficace</li><li>Résistance à <span class=\"kw-alerte\">2 antipsychotiques 2G</span> bien conduits → <span class=\"kw-ttt\">clozapine</span></li><li>Observance difficile → <span class=\"kw-ttt\">forme retard IM</span> [ROA]</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Durée : <span class=\"kw-chiffre\">≥ 2 ans</span> (1er épisode) / <span class=\"kw-chiffre\">≥ 5 ans</span> (rechute)</li><li>Dépister le <span class=\"kw-etio\">syndrome métabolique</span>, suivre l'<span class=\"kw-ttt\">observance</span> et la tolérance</li></ul>"}]},"cards":[{"i":"266058b2310e","n":63,"o":"63-1","u":"Définition","t":"Connaître la définition des idées délirantes et des hallucinations","q":"Quelle est la définition générale d'une hallucination ?","a":"<p>Une hallucination est une <strong>perception sans objet à percevoir</strong>.</p>"},{"i":"9725cfef9e5d","n":63,"o":"63-1","u":"Définition","t":"Connaître la définition des idées délirantes et des hallucinations","q":"Quelle est la définition d'une idée délirante dans le contexte de la schizophrénie ?","a":"<p>Une idée délirante est une <strong>altération du contenu de la pensée</strong> entraînant une <strong>perte du contact avec la réalité</strong>. Elle se caractérise par :</p><ul><li>Une <strong>déduction incorrecte</strong> concernant la réalité extérieure.</li><li>Une <strong>conviction inébranlable</strong>, maintenue malgré toute preuve du contraire ou l'opinion partagée.</li><li>Son <strong>inaccessibilité au raisonnement</strong> ou à la contestation par les faits.</li></ul>"},{"i":"a4fe9c25c1a5","n":63,"o":"63-1","u":"Définition","t":"Connaître la définition des idées délirantes et des hallucinations","q":"Quels sont les deux types d'hallucinations et leurs caractéristiques principales ?","a":"<ul><li>Les hallucinations <strong>intrapsychiques</strong> : elles se caractérisent par une <strong>perte de l'intimité psychique</strong>, une <strong>absence de sensorialité et de spatialité</strong>, et sont vécues dans la pensée du patient comme étant étrangères à lui.</li><li>Les hallucinations <strong>sensorielles</strong> : elles impliquent une <strong>présence de sensorialité, de spatialité et une conviction de réalité</strong>. Elles peuvent toucher les <strong>5 sens</strong> (auditif, visuel, tactile, olfactif/gustatif, cénesthésique).</li></ul>"},{"i":"f1c4a0ca93af","n":63,"o":"63-1","u":"Définition","t":"Connaître la définition des idées délirantes et des hallucinations","q":"Quel terme utilise-t-on quand une idée délirante est construite secondairement à partir d'une hallucination ?","a":"<p>On parle alors de <strong>mécanisme hallucinatoire</strong>.</p>"},{"i":"3ca7b22f29fb","n":63,"o":"63-10","u":"Diagnostic positif","t":"Connaître le syndrome positif","q":"Comment peuvent se manifester les hallucinations auditives dans le trouble schizophrénique et quels signes cliniques peuvent les évoquer ?","a":"<p>Les hallucinations auditives peuvent prendre la forme de sons simples, mais sont le plus souvent des <strong>hallucinations acoustico-verbales</strong>, avec des voix distinctement localisées dans l'espace qui conversent entre elles ou s'adressent au patient à la <strong>3ᵉ personne</strong>, souvent avec des phrases courtes et négatives.<br/>Les signes évocateurs sont : les <strong>attitudes d'écoute</strong>, des moyens de protection (musique, se boucher les oreilles), la <strong>soliloquie</strong> et une <strong>distractibilité</strong> pendant l'entretien.</p>"},{"i":"82f6e5d812db","n":63,"o":"63-10","u":"Diagnostic positif","t":"Connaître le syndrome positif","q":"Dans le cadre du trouble schizophrénique, que regroupe le syndrome positif ?","a":"<p>Le syndrome positif regroupe les <strong>productions psychiques en excès</strong>, qui se manifestent principalement par des <strong>idées délirantes</strong> et des <strong>hallucinations</strong>.</p>"},{"i":"8fb2813bb3d4","n":63,"o":"63-10","u":"Diagnostic positif","t":"Connaître le syndrome positif","q":"En schizophrénie, que sont les hallucinations intrapsychiques et quelle distinction fondamentale doit-on faire concernant les hallucinations ?","a":"<ul><li>Les <strong>hallucinations intrapsychiques</strong> sont des phénomènes vécus dans la pensée du patient, sans manifestation sensorielle extérieure, qui traduisent une perte de l'intimité psychique (vol, divulgation, devinement, transmission de la pensée, pensées imposées, écho de la pensée).</li><li>Il est crucial de noter qu'une <strong>hallucination n'est pas forcément délirante</strong>. Lorsque l'idée délirante en découle, on parle de <strong>mécanisme hallucinatoire</strong>.</li></ul>"},{"i":"9c4d76087c28","n":63,"o":"63-10","u":"Diagnostic positif","t":"Connaître le syndrome positif","q":"Quels sont les types sensoriels d'hallucinations les plus fréquents dans la schizophrénie, et leurs caractéristiques principales ?","a":"<ul><li>Les hallucinations <strong>auditives</strong> (environ <strong>50 %</strong> des cas) sont les plus fréquentes, souvent sous forme de sons simples ou d'<strong>hallucinations acoustico-verbales</strong> (voix conversant entre elles, s'adressant au sujet à la 3ᵉ personne, avec des phrases courtes à connotation négative).</li><li>Les hallucinations <strong>visuelles</strong> (environ <strong>30 %</strong> des cas) peuvent être élémentaires (lumières, taches) ou complexes (objets, figures).</li><li>Les hallucinations <strong>tactiles</strong> (environ <strong>5 %</strong> des cas) incluent des sensations de coups de vent, brûlures, piqûres ou parasites sur le corps.</li></ul>"},{"i":"a58890e67f94","n":63,"o":"63-10","u":"Diagnostic positif","t":"Connaître le syndrome positif","q":"Quels sont les thèmes et caractéristiques typiques des idées délirantes dans la schizophrénie ?","a":"<p>Les idées délirantes ont une prévalence <strong>supérieure à 90 %</strong> dans la schizophrénie. Leurs thèmes sont <strong>multiples et hétérogènes</strong>, les mécanismes variés, et le délire est le plus souvent <strong>non systématisé</strong>.</p>"},{"i":"2a35b82fd741","n":63,"o":"63-11","u":"Diagnostic positif","t":"Connaître le syndrome négatif","q":"Quelles sont les manifestations cognitives et comportementales du syndrome négatif de la schizophrénie ?","a":"<p>Les manifestations sont :</p><ul><li><strong>Alogie / pauvreté du discours</strong> : difficultés à converser, réponses brèves.</li><li><strong>Retrait social</strong> : vie relationnelle pauvre, sans recherche de contact.</li><li><strong>Aboulie</strong> : incapacité à mettre en œuvre une action déjà planifiée, par diminution de la motivation.</li><li><strong>Apragmatisme</strong> : incapacité à entreprendre et à planifier des actions, pouvant aller jusqu'à la <strong>clinophilie</strong> (rester au lit) puis l'<strong>incurie</strong> (négligence de l'hygiène).</li></ul>"},{"i":"3649d6480294","n":63,"o":"63-11","u":"Diagnostic positif","t":"Connaître le syndrome négatif","q":"Quelles sont les manifestations affectives du syndrome négatif de la schizophrénie ?","a":"<ul><li><strong>Anhédonie</strong> : perte de la capacité à éprouver du plaisir.</li><li><strong>Émoussement des affects</strong> : absence d'émotions dans l'expression du visage et l'intonation de la voix, avec un regard fixe, un corps figé et une impression de froideur.</li></ul>"},{"i":"5c4eadc9c5f3","n":63,"o":"63-11","u":"Diagnostic positif","t":"Connaître le syndrome négatif","q":"Quelle est la définition du syndrome négatif dans le trouble schizophrénique ?","a":"<p>Le syndrome négatif correspond à un <strong>appauvrissement de la vie psychique</strong> et conditionne fortement le pronostic fonctionnel du patient.</p>"},{"i":"52a2faa06d95","n":63,"o":"63-12","u":"Diagnostic positif","t":"Connaître le syndrome de désorganisation","q":"Quelles sont les manifestations affectives du syndrome de désorganisation dans la schizophrénie ?","a":"<ul><li><strong>Ambivalence affective</strong> : coexistence d'affects contradictoires simultanément pour un même objet.</li><li><strong>Réaction affective inappropriée</strong> ou <strong>discordance idéo-affective</strong> : incohérence entre le discours et les émotions exprimées (ex: sourires discordants, rires immotivés).</li></ul>"},{"i":"5f372a0f5a1d","n":63,"o":"63-12","u":"Diagnostic positif","t":"Connaître le syndrome de désorganisation","q":"Décrivez les manifestations comportementales typiques du syndrome de désorganisation schizophrénique.","a":"<ul><li><strong>Maniérisme gestuel</strong> : mauvaise coordination des mouvements.</li><li><strong>Ambivalence comportementale</strong>.</li><li><strong>Parakinésies</strong> : décharges motrices imprévisibles.</li><li><strong>Paramimies</strong> : discordance entre la mimique et le contenu psycho-affectif.</li></ul>"},{"i":"778a87ea1cfd","n":63,"o":"63-12","u":"Diagnostic positif","t":"Connaître le syndrome de désorganisation","q":"Comment le syndrome de désorganisation affecte-t-il le langage dans la schizophrénie ?","a":"<ul><li>Présence de <strong>néologismes</strong>.</li><li>Utilisation de <strong>paralogismes</strong>.</li><li>Au maximum, on peut observer une <strong>schizophasie</strong>, correspondant à un néo-langage incompréhensible.</li></ul>"},{"i":"9cee5b7152d4","n":63,"o":"63-12","u":"Diagnostic positif","t":"Connaître le syndrome de désorganisation","q":"Quelle est la définition du syndrome de désorganisation dans le cadre du trouble schizophrénique ?","a":"<p>Le syndrome de désorganisation est caractérisé par la <strong>perte de l'unité psychique</strong> entre les cognitions, les émotions et les comportements.</p>"},{"i":"da543df4602a","n":63,"o":"63-12","u":"Diagnostic positif","t":"Connaître le syndrome de désorganisation","q":"Quelles sont les manifestations cognitives affectant la pensée et la logique dans le syndrome de désorganisation schizophrénique ?","a":"<ul><li>Concernant la pensée : <strong>discours diffluent</strong>, propos décousus.</li><li><strong>Barrages</strong> : interruption brusque du discours.</li><li><strong>Fading</strong> : ralentissement et baisse du volume sonore du discours.</li><li>Concernant la logique : <strong>rationalisme morbide</strong>, <strong>raisonnement paralogique</strong>, altération des capacités d'abstraction.</li></ul>"},{"i":"1547d18d238f","n":63,"o":"63-13","u":"Identifier une urgence","t":"Connaître les principaux diagnostics différentiels non psychiatriques","q":"Quelle cause non psychiatrique est considérée comme une urgence diagnostique absolue car elle peut se présenter comme un premier épisode psychotique et est grave si non traitée ?","a":"<p>L'<strong>encéphalite</strong> (herpétique ou auto-immune à anticorps anti-neuronaux) est une urgence diagnostique majeure. Tout tableau atypique impose un bilan organique rapide pour exclure cette pathologie.</p>"},{"i":"3951c2bcda45","n":63,"o":"63-13","u":"Identifier une urgence","t":"Connaître les principaux diagnostics différentiels non psychiatriques","q":"Quelles sont les principales causes endocriniennes, métaboliques et infectieuses non psychiatriques pouvant simuler un tableau psychotique ?","a":"<ul><li>Endocriniennes : <strong>Dysthyroïdies</strong>, <strong>altération de l'axe corticotrope</strong></li><li>Métaboliques : <strong>Maladie de Wilson</strong>, <strong>Maladie de Niemann-Pick type C</strong></li><li>Infectieuses : <strong>Neurosyphilis</strong>, <strong>SIDA</strong></li></ul>"},{"i":"513bcb31775a","n":63,"o":"63-13","u":"Identifier une urgence","t":"Connaître les principaux diagnostics différentiels non psychiatriques","q":"Quel bilan paraclinique minimal faut-il réaliser systématiquement pour éliminer une cause organique ou toxique devant un premier épisode psychotique ?","a":"<ul><li>Bilan biologique standard : <strong>glycémie</strong>, <strong>NFS</strong>, <strong>CRP</strong>, <strong>ionogramme</strong>, <strong>urée</strong>, <strong>créatinine</strong>, <strong>bilan hépatique</strong>, <strong>calcémie</strong>, <strong>TSH</strong></li><li>Recherche de toxiques urinaires : <strong>cannabis</strong>, <strong>cocaïne</strong>, <strong>opioïdes</strong>, <strong>amphétamines</strong></li><li><strong>Imagerie cérébrale (IRM au mieux)</strong>, surtout si signe d'appel ou présentation atypique</li><li><strong>EEG</strong>, utile lors d'un premier épisode pour éliminer une comitialité</li></ul>"},{"i":"99a784dbc9da","n":63,"o":"63-13","u":"Identifier une urgence","t":"Connaître les principaux diagnostics différentiels non psychiatriques","q":"Quelles sont les substances psychoactives dont l'intoxication aiguë ou chronique peut mimer un tableau psychotique ?","a":"<ul><li><strong>Cannabis</strong></li><li><strong>Amphétamines</strong></li><li><strong>Anticholinergiques</strong></li><li><strong>LSD</strong></li><li><strong>Kétamine</strong></li><li><strong>Phencyclidine</strong></li></ul>"},{"i":"bc73b514aee8","n":63,"o":"63-13","u":"Identifier une urgence","t":"Connaître les principaux diagnostics différentiels non psychiatriques","q":"Pourquoi est-il crucial d'éliminer systématiquement une cause organique ou toxique devant un tableau psychotique, en particulier un premier épisode, avant de retenir un diagnostic de schizophrénie ?","a":"<p>Il est crucial d'éliminer une cause organique ou toxique car plusieurs pathologies non psychiatriques peuvent imiter un tableau psychotique, et leur diagnostic est une <strong>urgence vitale ou fonctionnelle</strong>. Cela permet d'éviter l'étiquetage précoce d'une maladie psychiatrique et de mettre en œuvre un traitement spécifique et souvent urgent de la cause sous-jacente.</p>"},{"i":"c3c67c5fa439","n":63,"o":"63-13","u":"Identifier une urgence","t":"Connaître les principaux diagnostics différentiels non psychiatriques","q":"Quelles sont les principales causes neurologiques non psychiatriques pouvant se manifester par un tableau psychotique ?","a":"<ul><li><strong>Épilepsie</strong></li><li><strong>Tumeurs cérébrales</strong></li><li><strong>Encéphalite herpétique ou à anticorps anti-neuronaux</strong></li><li><strong>Maladie de Huntington</strong></li><li><strong>Neurolupus</strong></li></ul>"},{"i":"1b3ecf4ad84a","n":63,"o":"63-16","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique de la phase aiguë","q":"Quand doit-on initier ou modifier un traitement pharmacologique lors d'un épisode aigu de trouble schizophrénique ?","a":"<p>Le traitement antipsychotique doit impérativement être initié ou modifié <strong>rapidement</strong> dès la recrudescence des symptômes (idées délirantes, hallucinations, désorganisation, repli).</p>"},{"i":"2698a5c4cf2b","n":63,"o":"63-16","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique de la phase aiguë","q":"Quel traitement pharmacologique peut être associé en cas d'anxiété ou d'agitation modérée lors d'un épisode aigu de schizophrénie ?","a":"Si une anxiété ou une agitation modérée est présente, un traitement symptomatique sédatif est associé parmi 2 options :\n<ul>\n<li>Des <strong>antipsychotiques \"sédatifs\" de 1ère génération</strong>, tels que la <strong>cyamémazine</strong> ou la <strong>lévomépromazine</strong>.</li>\n<li>Des <strong>benzodiazépines</strong>, telles que le <strong>diazépam</strong> ou l'<strong>oxazépam</strong>, qui facilitent la prise en charge et l'introduction de l'antipsychotique principal.</li>\n</ul>"},{"i":"9d9bde4f9293","n":63,"o":"63-16","u":"Prise en charge","t":"Connaître les indications du traitement pharmacologique de la phase aiguë","q":"Pourquoi la prise en charge pharmacologique de l'épisode aigu de schizophrénie est-elle considérée comme une urgence thérapeutique ?","a":"<p>Il s'agit d'une <strong>urgence thérapeutique</strong> car même si le diagnostic de schizophrénie requiert habituellement 1 mois de symptômes, le traitement doit être initié sans délai en cas d'épisode aigu pour maximiser son efficacité et éviter la pérennisation des symptômes.</p>"},{"i":"b2151a792847","n":63,"o":"63-2","u":"Définition","t":"Connaître la définition des schizophrénies","q":"Comment la durée du retentissement fonctionnel permet-elle de différencier la schizophrénie d'autres troubles psychotiques ?","a":"<ul><li>Si le retentissement dure <strong>1 jour à 1 mois</strong> : on parle de <strong>trouble psychotique bref</strong>.</li><li>Si le retentissement dure <strong>1 à 6 mois</strong> : on parle de <strong>trouble schizophréniforme</strong>.</li><li>Si le retentissement dure <strong>≥ 6 mois</strong> : on parle alors de <strong>schizophrénie</strong>.</li></ul>"},{"i":"cd9a89616c77","n":63,"o":"63-2","u":"Définition","t":"Connaître la définition des schizophrénies","q":"Quelle est la définition générale de la schizophrénie selon le contenu de l'objectif ?","a":"<p>La schizophrénie est un <strong>trouble psychiatrique fréquent</strong>, classé parmi les 10 maladies les plus invalidantes par l'OMS. Elle fait partie des <strong>troubles psychotiques chroniques</strong>, caractérisés par une altération du contact avec la réalité.</p>"},{"i":"dae4eee43337","n":63,"o":"63-2","u":"Définition","t":"Connaître la définition des schizophrénies","q":"Quels sont les critères diagnostiques sur lesquels repose le diagnostic positif de la schizophrénie ?","a":"<ul><li>Association d'au moins <strong>deux syndromes</strong> parmi le syndrome positif, le syndrome négatif ou le syndrome de désorganisation.</li><li>Symptômes de la phase active présents <strong>≥ 1 mois</strong> (ou moins en cas de traitement efficace).</li><li><strong>Retentissement fonctionnel social ou professionnel</strong> depuis le début des troubles.</li><li><strong>Durée totale d'évolution ≥ 6 mois</strong>.</li></ul>"},{"i":"345e3d4abba6","n":63,"o":"63-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quels sont les cinq axes sémiologiques à analyser devant tout syndrome délirant en psychiatrie ?","a":"<p>Devant tout syndrome délirant, l'analyse sémiologique s'articule autour de cinq axes principaux :</p><ul><li>Le <strong>thème</strong> du délire.</li><li>Le <strong>mécanisme</strong> de production du délire.</li><li>La <strong>systématisation</strong> du délire.</li><li>L'<strong>adhésion</strong> du patient à ses idées délirantes.</li><li>Le <strong>retentissement</strong> du délire.</li></ul>"},{"i":"70c6f4b5676b","n":63,"o":"63-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Comment la systématisation et l'adhésion au délire se distinguent-elles entre la schizophrénie et le trouble délirant persistant ?","a":"<p>La distinction se fait comme suit :</p><ul><li><strong>Systématisation</strong> : Dans la schizophrénie, le délire est généralement <strong>non systématisé</strong>, avec une organisation floue, incohérente et sans logique. Dans le trouble délirant persistant, il est majoritairement <strong>systématisé</strong>, présentant une logique apparente.</li><li><strong>Adhésion</strong> : Dans la schizophrénie, l'adhésion est <strong>variable</strong> (partielle, avec critique possible, ou totale). Dans le trouble délirant persistant, l'adhésion est généralement <strong>totale</strong>, avec une conviction inébranlable.</li></ul>"},{"i":"b1ec9e65807c","n":63,"o":"63-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quels sont les thèmes délirants les plus fréquemment rencontrés dans le trouble schizophrénique ?","a":"<p>Les thèmes délirants les plus fréquents dans la schizophrénie incluent :</p><ul><li>Le thème de la <strong>persécution</strong> : le patient se sent attaqué, harcelé, espionné.</li><li>Le thème de <strong>grandeur</strong> ou <strong>mégalomaniaque</strong> : sentiment exagéré de son importance ou de son pouvoir.</li><li>Le thème <strong>mystique</strong> : délire à contenu religieux.</li><li>Le thème <strong>somatique</strong> : idées délirantes concernant le fonctionnement du corps.</li><li>Le thème de <strong>référence</strong> : des éléments de l'environnement auraient une signification particulière pour le patient.</li></ul>"},{"i":"ba2bd1f9da52","n":63,"o":"63-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quels sont les principaux mécanismes de construction de l'idée délirante et comment se manifestent-ils ?","a":"<p>Les principaux mécanismes délirants sont :</p><ul><li>Le mécanisme <strong>interprétatif</strong> : attribution d'un sens erroné à un fait réel.</li><li>Le mécanisme <strong>hallucinatoire</strong> : l'idée délirante est construite à partir d'une hallucination.</li><li>Le mécanisme <strong>intuitif</strong> : l'idée fausse est admise sans vérification ni raisonnement, en dehors de toute donnée objective.</li><li>Le mécanisme <strong>imaginatif</strong> : l'imagination est au premier plan, avec des fabulations ou inventions.</li></ul>"},{"i":"f3981cb96fac","n":63,"o":"63-8","u":"Diagnostic positif","t":"Connaître l’analyse sémiologique d’un syndrome délirant","q":"Quel est le retentissement à évaluer systématiquement face à un syndrome délirant ?","a":"<p>Face à un syndrome délirant, il est impératif d'évaluer le <strong>retentissement émotionnel et comportemental</strong>, cela inclut :</p><ul><li>Le niveau d'<strong>anxiété</strong> du patient, qui est souvent majeur.</li><li>Le <strong>risque suicidaire</strong>.</li><li>Le <strong>risque de passage à l'acte hétéro-agressif</strong>, motivé par des idées délirantes (e.g., venger ses fautes, se venger d'un persécuteur).</li></ul>"}]};